<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import PanelCard from '@/components/PanelCard.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { useEmsStore } from '@/stores/ems'
const props = defineProps<{ section: 'strategies' | 'types' | 'issue' | 'schedule' | 'logs' | 'commands' }>()
const store = useEmsStore()
const modal = ref(false)
const editingId = ref('')
const form = reactive({ name: '', type: '削峰填谷', priority: 1, power: '500.0 kW', targetSoc: '75.00%', schedule: '', trigger: '' })
const title = computed(() => ({ strategies: '策略管理', types: '策略类型', issue: '策略下发', schedule: '策略调度计划', logs: '策略执行日志', commands: '实时调度指令' }[props.section]))
const subtitle = computed(() => ({ strategies: '储能运行策略创建、编辑与版本维护', types: '储能调度策略类型与参数项', issue: '策略下发、暂停与停止控制', schedule: '日、周、月策略调度计划', logs: '策略执行记录与结果追踪', commands: '实时指令与PCS响应状态' }[props.section]))
const openStrategy = (strategy?: typeof store.strategies[number]) => { editingId.value = strategy?.id || ''; Object.assign(form, strategy || { name: '新增削峰填谷策略', type: '削峰填谷', priority: 1, power: '500.0 kW', targetSoc: '75.00%', schedule: '每日10:00-15:00、18:00-22:00', trigger: '电价≥0.9元且负荷>2000kW' }); modal.value = true }
const saveStrategy = () => { editingId.value ? store.updateStrategy(editingId.value, form) : store.createStrategy(form.name); modal.value = false }
const strategyTypes = [{ name: '削峰填谷', desc: '按峰平谷电价执行谷充峰放，计算价差收益', fields: '时段、动作、功率、SOC目标' }, { name: '需量管理', desc: '根据15分钟平均功率预测，提前释放储能削峰', fields: '需量阈值、预测窗口、削峰功率' }, { name: '调频', desc: '跟随频率偏差或调度指令进行快速功率响应', fields: '响应倍率、死区、爬坡率' }, { name: '防逆流', desc: '光伏出力大于负荷时提升充电功率，控制并网点功率', fields: '反向功率阈值、吸收功率、SOC上限' }, { name: '离网备电', desc: '并网点异常时切换离网供电，保障重要负荷', fields: '备电SOC、负荷优先级、切换时间' }]
</script>
<template>
  <div class="page-grid tob-page"><PanelCard class="span-12" :title="title" :subtitle="subtitle"><template #action><el-tag type="success">实时刷新 {{ store.snapshot.timestamp }}</el-tag></template></PanelCard>
    <PanelCard v-if="section === 'strategies'" class="span-12" title="策略管理列表" subtitle="储能运行策略"><template #action><el-button type="primary" @click="openStrategy()">新增策略</el-button></template><el-table :data="store.strategies" stripe><el-table-column label="策略名称" min-width="210"><template #default="{ row }"><strong>{{ row.name }}</strong><small>{{ row.trigger }}</small></template></el-table-column><el-table-column prop="type" label="类型"/><el-table-column prop="priority" label="优先级" width="80"/><el-table-column prop="targetSoc" label="目标SOC"/><el-table-column prop="power" label="功率"/><el-table-column prop="version" label="版本"/><el-table-column label="状态"><template #default="{ row }"><StatusBadge :text="row.status" /></template></el-table-column><el-table-column label="操作" width="150"><template #default="{ row }"><el-button link type="primary" @click="openStrategy(row)">编辑</el-button><el-button link type="danger" @click="store.deleteStrategy(row.id)">删除</el-button></template></el-table-column></el-table></PanelCard>
    <PanelCard v-else-if="section === 'types'" class="span-12" title="策略类型" subtitle="五类储能调度策略"><div class="rule-grid"><article v-for="item in strategyTypes" :key="item.name"><strong>{{ item.name }}</strong><span>{{ item.desc }}</span><em>{{ item.fields }}</em></article></div></PanelCard>
    <PanelCard v-else-if="section === 'issue'" class="span-12" title="策略下发" subtitle="EMS执行控制"><el-table :data="store.strategies" stripe><el-table-column prop="name" label="策略"/><el-table-column label="状态"><template #default="{ row }"><StatusBadge :text="row.status" /></template></el-table-column><el-table-column prop="schedule" label="计划"/><el-table-column prop="trigger" label="触发条件"/><el-table-column label="操作" width="210"><template #default="{ row }"><el-button link type="primary" @click="store.issueStrategy(row.id)">下发执行</el-button><el-button link @click="store.updateStrategy(row.id, { status: '暂停' })">暂停</el-button><el-button link type="danger" @click="store.updateStrategy(row.id, { status: '停止' })">停止</el-button></template></el-table-column></el-table></PanelCard>
    <PanelCard v-else-if="section === 'schedule'" class="span-12" title="策略调度计划" subtitle="策略时间计划"><div class="timeline"><article v-for="strategy in store.strategies" :key="strategy.id"><strong>{{ strategy.name }}</strong><span>{{ strategy.schedule }} · {{ strategy.trigger }}</span></article></div><div class="calendar-grid"><span v-for="day in ['周一','周二','周三','周四','周五','周六','周日']" :key="day">{{ day }}<em>峰段放电 / 谷段充电</em></span></div></PanelCard>
    <PanelCard v-else-if="section === 'logs'" class="span-12" title="策略执行日志" subtitle="执行记录与结果"><el-table :data="store.logs" stripe><el-table-column prop="time" label="时间"/><el-table-column prop="event" label="事件"/><el-table-column prop="result" label="执行结果"/></el-table></PanelCard>
    <PanelCard v-else class="span-12" title="实时调度指令" subtitle="当前下发指令与响应状态"><div class="detail-grid"><article><label>当前指令</label><strong>{{ store.snapshot.mode }}指令</strong></article><article><label>目标功率</label><strong>{{ store.format.kw(Math.abs(store.snapshot.storagePower)) }}</strong></article><article><label>当前SOC</label><strong>{{ store.format.pct(store.snapshot.soc) }}</strong></article><article><label>PCS响应</label><strong>闭环跟随正常，通讯延迟28ms</strong></article><article><label>更新时间</label><strong>{{ store.snapshot.timestamp }}</strong></article></div></PanelCard>
    <el-dialog v-model="modal" title="策略维护" width="680px"><el-form :model="form" label-width="90px"><el-form-item label="策略名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="策略类型"><el-select v-model="form.type"><el-option v-for="item in strategyTypes" :key="item.name" :label="item.name" :value="item.name" /></el-select></el-form-item><el-form-item label="优先级"><el-input v-model.number="form.priority" type="number" /></el-form-item><el-form-item label="目标功率"><el-input v-model="form.power" /></el-form-item><el-form-item label="SOC目标"><el-input v-model="form.targetSoc" /></el-form-item><el-form-item label="调度计划"><el-input v-model="form.schedule" /></el-form-item><el-form-item label="触发条件"><el-input v-model="form.trigger" /></el-form-item></el-form><template #footer><el-button @click="modal = false">取消</el-button><el-button type="primary" @click="saveStrategy">保存</el-button></template></el-dialog>
  </div>
</template>
