<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import type { EChartsOption } from 'echarts'
import ChartBox from '@/components/ChartBox.vue'
import KpiCard from '@/components/KpiCard.vue'
import PanelCard from '@/components/PanelCard.vue'
import PowerFlow from '@/components/PowerFlow.vue'
import { useEmsStore } from '@/stores/ems'

const props = defineProps<{ section: 'overview' | 'revenue' | 'energy' | 'tariff' | 'demand' }>()
const store = useEmsStore()
const tariffModal = ref(false)
const tariffForm = reactive({ period: '', price: 0 })
const title = computed(() => ({ overview: '运营总览', revenue: '收益明细', energy: '充放电统计', tariff: '电价管理', demand: '需量管理' }[props.section]))
const subtitle = computed(() => ({ overview: '电站收益、能量、效率与功率流向', revenue: '收益分项与趋势分析', energy: '充放电量统计与峰谷分布', tariff: '分时电价策略维护', demand: '十五分钟需量曲线与削峰效果' }[props.section]))
const openTariff = (item: typeof store.tariffs[number]) => { Object.assign(tariffForm, item); tariffModal.value = true }
const saveTariff = () => { store.updateTariff(tariffForm.period, Number(tariffForm.price)); tariffModal.value = false }
const powerOption = computed<EChartsOption>(() => ({ tooltip: { trigger: 'axis' }, legend: { top: 4 }, grid: { left: 42, right: 24, top: 44, bottom: 32 }, xAxis: { type: 'category', data: ['00', '04', '08', '12', '16', '20', '24'] }, yAxis: { type: 'value' }, series: [{ name: '负荷', type: 'line', smooth: true, data: [820, 760, 1680, store.snapshot.loadPower, 1860, 2280, 920] }, { name: '光伏', type: 'line', smooth: true, data: [0, 0, 180, store.snapshot.pvPower, 360, 0, 0] }, { name: '储能', type: 'bar', data: [-520, -480, 0, store.snapshot.storagePower, 0, 680, -430] }] }))
const revenueOption = computed<EChartsOption>(() => ({ tooltip: { trigger: 'axis' }, legend: { top: 4 }, grid: { left: 42, right: 24, top: 44, bottom: 32 }, xAxis: { type: 'category', data: ['周一', '周二', '周三', '周四', '周五', '周六', '周日'] }, yAxis: { type: 'value' }, series: [{ name: '削峰填谷', type: 'bar', stack: '收益', data: [3260, 3480, 3860, store.snapshot.todayRevenue, 3980, 2760, 2880] }, { name: '需量管理', type: 'bar', stack: '收益', data: [820, 760, 910, 960, 880, 520, 560] }, { name: '调频收益', type: 'line', data: [260, 320, 300, 360, 340, 280, 310] }] }))
const energyOption = computed<EChartsOption>(() => ({ tooltip: { trigger: 'item' }, series: [{ type: 'pie', radius: ['45%', '70%'], data: [{ name: '谷时充电', value: store.snapshot.chargeEnergy }, { name: '峰时放电', value: store.snapshot.dischargeEnergy }, { name: '平时待机', value: 420 }] }] }))
const revenueRows = computed(() => [{ name: '削峰填谷', today: '3,260.18 元', month: '62,186.34 元', year: '468,320.88 元', desc: '峰放谷充价差' }, { name: '需量管理', today: '820.45 元', month: '18,216.00 元', year: '132,480.00 元', desc: '削减最大需量' }, { name: '调频收益', today: '310.20 元', month: '6,018.04 元', year: '42,117.84 元', desc: '响应调度指令' }])
</script>

<template>
  <div class="page-grid tob-page">
    <PanelCard class="span-12" :title="title" :subtitle="subtitle"><template #action><el-tag type="success">实时刷新 {{ store.snapshot.timestamp }}</el-tag></template></PanelCard>
    <template v-if="section === 'overview'"><KpiCard label="今日净收益" :value="store.format.yuan(store.snapshot.todayRevenue)" hint="实时累计" tone="green" /><KpiCard label="SOC" :value="store.format.pct(store.snapshot.soc)" hint="安全运行区间" tone="blue" /><KpiCard label="充电电量" :value="store.format.kwh(store.snapshot.chargeEnergy)" hint="当日累计" tone="green" /><KpiCard label="综合效率" value="91.72%" hint="循环效率" tone="orange" /><PanelCard class="span-8" title="实时功率流向" subtitle="负荷、光伏、储能、并网点功率"><PowerFlow /></PanelCard><PanelCard class="span-4" title="收益构成" subtitle="运营关键指标"><div class="report-grid"><article><strong>3,260.18</strong><span>削峰填谷收益 元</span></article><article><strong>820.45</strong><span>需量收益 元</span></article><article><strong>310.20</strong><span>调频收益 元</span></article><article><strong>486.32</strong><span>CO₂减排 kg</span></article></div></PanelCard></template>
    <PanelCard v-else-if="section === 'revenue'" class="span-12" title="收益明细" subtitle="削峰填谷、需量管理、调频收益分项展示与趋势"><ChartBox :option="revenueOption" :updated-at="store.snapshot.timestamp" /><el-table :data="revenueRows" stripe><el-table-column prop="name" label="收益项" /><el-table-column prop="today" label="今日" /><el-table-column prop="month" label="本月" /><el-table-column prop="year" label="本年" /><el-table-column prop="desc" label="说明" /></el-table></PanelCard>
    <PanelCard v-else-if="section === 'energy'" class="span-12" title="充放电统计" subtitle="日/月/年充放电量统计与峰谷时段分布"><div class="split"><ChartBox :option="energyOption" :updated-at="store.snapshot.timestamp" /><ChartBox :option="powerOption" :updated-at="store.snapshot.timestamp" /></div></PanelCard>
    <PanelCard v-else-if="section === 'tariff'" class="span-12" title="电价管理" subtitle="峰、平、谷分时电价维护"><el-table :data="store.tariffs" stripe><el-table-column prop="period" label="时段" /><el-table-column prop="type" label="类型"><template #default="{ row }"><el-tag :type="row.type === '峰' ? 'danger' : row.type === '谷' ? 'success' : 'warning'">{{ row.type }}</el-tag></template></el-table-column><el-table-column label="电价"><template #default="{ row }">{{ row.price.toFixed(2) }} 元/kWh</template></el-table-column><el-table-column label="适用日期" value="工作日、节假日独立配置" /><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click="openTariff(row)">编辑</el-button></template></el-table-column></el-table></PanelCard>
    <PanelCard v-else class="span-12" title="需量管理" subtitle="15分钟平均功率曲线与节费结果"><ChartBox :option="powerOption" :updated-at="store.snapshot.timestamp" /><div class="demand-row"><div><strong>2,486.0 kW</strong><span>无储能最大需量</span></div><div><strong>1,934.0 kW</strong><span>储能削峰后需量</span></div><div><strong>18,216.00 元</strong><span>需量电费节省</span></div></div></PanelCard>
    <el-dialog v-model="tariffModal" title="电价维护" width="520px"><el-form :model="tariffForm" label-width="80px"><el-form-item label="时段"><el-input v-model="tariffForm.period" disabled /></el-form-item><el-form-item label="电价"><el-input v-model.number="tariffForm.price" type="number" /></el-form-item></el-form><template #footer><el-button @click="tariffModal = false">取消</el-button><el-button type="primary" @click="saveTariff">保存</el-button></template></el-dialog>
  </div>
</template>
