<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import PanelCard from '@/components/PanelCard.vue'
import PowerFlow from '@/components/PowerFlow.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { useEmsStore, type Device, type DeviceType, type Station, type ThingModel } from '@/stores/ems'

const props = defineProps<{ section: 'models' | 'devices' | 'points' | 'station' | 'launch' | 'topology' }>()
const store = useEmsStore()
const modal = ref<'model' | 'device' | 'point' | 'station' | ''>('')
const editingId = ref('')
const modelForm = reactive({ name: '', type: 'PCS' as DeviceType, version: 'V1.0' })
const deviceForm = reactive({ name: '', modelId: '', ip: '', port: 502, interval: '1s' })
const pointForm = reactive({ id: '', device: '', address: '', type: 'Float32', unit: 'kW', scale: '0.1', desc: '' })
const stationForm = reactive({ name: '', location: '', capacity: '', powerRating: '', gridVoltage: '', transformerRatio: '', gridPoint: '' })
const steps = ['创建物模型', '实例化设备', '配置点表', '创建电站', '电站投运']
const title = computed(() => ({ models: '物模型管理', devices: '设备实例化', points: '点表配置', station: '电站创建', launch: '电站投运', topology: '设备拓扑展示' }[props.section]))
const subtitle = computed(() => ({ models: '设备标准属性、遥测、遥信与控制命令维护', devices: '设备通讯参数、协议与采集间隔配置', points: '设备寄存器地址与业务字段映射维护', station: '电站基础信息、容量参数与并网参数配置', launch: '设备通讯初始化、点表解析与采集状态启动', topology: '电站内设备电气连接与通讯拓扑' }[props.section]))

watch(() => props.section, () => { modal.value = ''; editingId.value = '' })
const openModel = (model?: ThingModel) => { editingId.value = model?.id || ''; Object.assign(modelForm, { name: model?.name || '', type: model?.type || 'PCS', version: model?.version || 'V1.0' }); modal.value = 'model' }
const saveModel = () => { editingId.value ? store.updateThingModel(editingId.value, { name: modelForm.name, version: modelForm.version }) : store.createThingModel(modelForm.type, modelForm.name); modal.value = '' }
const openDevice = (device?: Device) => { editingId.value = device?.id || ''; Object.assign(deviceForm, { name: device?.name || '', modelId: device?.modelId || store.thingModels[0]?.id || '', ip: device?.ip || '10.20.1.50', port: device?.port || 502, interval: device?.interval || '1s' }); modal.value = 'device' }
const saveDevice = () => { editingId.value ? store.updateDevice(editingId.value, deviceForm) : store.instantiateDevice(deviceForm.modelId, deviceForm.name); modal.value = '' }
const openPoint = (point?: typeof store.pointMappings[number]) => { editingId.value = point?.id || ''; Object.assign(pointForm, point || { id: '', device: store.station.devices[0]?.name || '', address: '42600', type: 'Float32', unit: 'kW', scale: '0.1', desc: '有功功率' }); modal.value = 'point' }
const savePoint = () => { editingId.value ? store.updatePointMapping(editingId.value, pointForm) : store.createPointMapping(pointForm.device); modal.value = '' }
const openStation = () => { editingId.value = store.station.id; Object.assign(stationForm, store.station); modal.value = 'station' }
const saveStation = () => { store.updateStation(stationForm as Partial<Station>); modal.value = '' }
</script>

<template>
  <div class="page-grid tob-page">
    <PanelCard class="span-12" :title="title" :subtitle="subtitle">
      <template #action><el-tag type="primary">{{ store.user.role }}</el-tag></template>
      <div class="stepper"><article v-for="(step, index) in steps" :key="step" :class="{ done: store.commissioningStep > index, active: store.commissioningStep === index + 1 }"><strong>{{ index + 1 }}</strong><span>{{ step }}</span></article></div>
    </PanelCard>

    <PanelCard v-if="section === 'models'" class="span-12" title="物模型列表" subtitle="PCS、BMS、电表、变压器物模型">
      <template #action><el-button type="primary" @click="openModel()">新增物模型</el-button></template>
      <el-table :data="store.thingModels" stripe><el-table-column prop="name" label="名称" min-width="170" /><el-table-column prop="type" label="类型" width="90" /><el-table-column label="属性" min-width="190"><template #default="{ row }">{{ row.properties.join('，') }}</template></el-table-column><el-table-column label="遥测" min-width="190"><template #default="{ row }">{{ row.telemetry.join('，') }}</template></el-table-column><el-table-column prop="version" label="版本" width="90" /><el-table-column label="操作" width="150" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openModel(row)">编辑</el-button><el-button link type="danger" @click="store.deleteThingModel(row.id)">删除</el-button></template></el-table-column></el-table>
    </PanelCard>

    <PanelCard v-else-if="section === 'devices'" class="span-12" title="设备实例列表" subtitle="设备通讯参数与运行状态">
      <template #action><el-button type="primary" @click="openDevice()">新增设备</el-button></template>
      <el-table :data="store.station.devices" stripe><el-table-column prop="name" label="设备名称" min-width="170" /><el-table-column prop="type" label="类型" width="90" /><el-table-column prop="model" label="物模型" min-width="180" /><el-table-column prop="protocol" label="协议" width="120" /><el-table-column prop="ip" label="IP" width="120" /><el-table-column prop="port" label="端口" width="90" /><el-table-column label="状态" width="120"><template #default="{ row }"><StatusBadge :text="row.status" /></template></el-table-column><el-table-column label="操作" width="150"><template #default="{ row }"><el-button link type="primary" @click="openDevice(row)">编辑</el-button><el-button link type="danger" @click="store.deleteDevice(row.id)">删除</el-button></template></el-table-column></el-table>
    </PanelCard>

    <PanelCard v-else-if="section === 'points'" class="span-12" title="点表配置列表" subtitle="测点映射、寄存器地址、单位与缩放系数">
      <template #action><el-button type="primary" @click="openPoint()">新增测点</el-button></template>
      <el-table :data="store.pointMappings" stripe><el-table-column prop="id" label="测点ID" width="110" /><el-table-column prop="device" label="设备" min-width="170" /><el-table-column prop="address" label="寄存器地址" width="120" /><el-table-column prop="type" label="数据类型" width="110" /><el-table-column prop="unit" label="单位" width="80" /><el-table-column prop="scale" label="缩放系数" width="100" /><el-table-column prop="desc" label="描述" /><el-table-column label="操作" width="150"><template #default="{ row }"><el-button link type="primary" @click="openPoint(row)">编辑</el-button><el-button link type="danger" @click="store.deletePointMapping(row.id)">删除</el-button></template></el-table-column></el-table>
    </PanelCard>

    <PanelCard v-else-if="section === 'station'" class="span-12" title="电站信息" subtitle="基础属性、并网参数与容量参数">
      <template #action><el-button type="primary" @click="openStation">编辑电站</el-button></template>
      <div class="detail-grid"><article><label>电站名称</label><strong>{{ store.station.name }}</strong></article><article><label>位置</label><strong>{{ store.station.location }}</strong></article><article><label>储能容量</label><strong>{{ store.station.capacity }}</strong></article><article><label>额定功率</label><strong>{{ store.station.powerRating }}</strong></article><article><label>并网电压</label><strong>{{ store.station.gridVoltage }}</strong></article><article><label>并网点</label><strong>{{ store.station.gridPoint }}</strong></article></div>
    </PanelCard>

    <PanelCard v-else-if="section === 'launch'" class="span-12" title="电站投运" subtitle="投运检查与启动记录">
      <div class="launch-checks"><p>物模型：{{ store.thingModels.length }} 套</p><p>设备实例：{{ store.station.devices.length }} 台</p><p>点表映射：{{ store.pointMappings.length }} 个</p><p>电站状态：{{ store.station.status }}</p><el-button type="primary" @click="store.commissionStation">一键投运</el-button></div>
      <div class="timeline"><article v-for="log in store.logs.slice(0, 8)" :key="log.time + log.event"><strong>{{ log.time }}</strong><span>{{ log.event }} · {{ log.result }}</span></article></div>
    </PanelCard>

    <PanelCard v-else class="span-12" title="设备拓扑展示" subtitle="电气连接与通讯链路状态"><PowerFlow /></PanelCard>

    <el-dialog v-model="modal" :title="modal === 'model' ? '物模型维护' : modal === 'device' ? '设备实例维护' : modal === 'point' ? '点表维护' : '电站属性维护'" width="680px">
      <el-form v-if="modal === 'model'" :model="modelForm" label-width="90px"><el-form-item label="模型名称"><el-input v-model="modelForm.name" /></el-form-item><el-form-item label="设备类型"><el-select v-model="modelForm.type"><el-option label="PCS" value="PCS" /><el-option label="BMS" value="BMS" /><el-option label="电表" value="电表" /><el-option label="变压器" value="变压器" /></el-select></el-form-item><el-form-item label="版本"><el-input v-model="modelForm.version" /></el-form-item></el-form>
      <el-form v-else-if="modal === 'device'" :model="deviceForm" label-width="90px"><el-form-item label="设备名称"><el-input v-model="deviceForm.name" /></el-form-item><el-form-item label="物模型"><el-select v-model="deviceForm.modelId"><el-option v-for="model in store.thingModels" :key="model.id" :label="model.name" :value="model.id" /></el-select></el-form-item><el-form-item label="IP地址"><el-input v-model="deviceForm.ip" /></el-form-item><el-form-item label="端口"><el-input v-model.number="deviceForm.port" /></el-form-item><el-form-item label="采集间隔"><el-input v-model="deviceForm.interval" /></el-form-item></el-form>
      <el-form v-else-if="modal === 'point'" :model="pointForm" label-width="90px"><el-form-item label="设备"><el-select v-model="pointForm.device"><el-option v-for="device in store.station.devices" :key="device.id" :label="device.name" :value="device.name" /></el-select></el-form-item><el-form-item label="寄存器地址"><el-input v-model="pointForm.address" /></el-form-item><el-form-item label="数据类型"><el-input v-model="pointForm.type" /></el-form-item><el-form-item label="单位"><el-input v-model="pointForm.unit" /></el-form-item><el-form-item label="缩放系数"><el-input v-model="pointForm.scale" /></el-form-item><el-form-item label="描述"><el-input v-model="pointForm.desc" /></el-form-item></el-form>
      <el-form v-else :model="stationForm" label-width="100px"><el-form-item label="电站名称"><el-input v-model="stationForm.name" /></el-form-item><el-form-item label="位置"><el-input v-model="stationForm.location" /></el-form-item><el-form-item label="储能容量"><el-input v-model="stationForm.capacity" /></el-form-item><el-form-item label="额定功率"><el-input v-model="stationForm.powerRating" /></el-form-item><el-form-item label="并网电压"><el-input v-model="stationForm.gridVoltage" /></el-form-item><el-form-item label="变压器变比"><el-input v-model="stationForm.transformerRatio" /></el-form-item><el-form-item label="并网点"><el-input v-model="stationForm.gridPoint" /></el-form-item></el-form>
      <template #footer><el-button @click="modal = ''">取消</el-button><el-button type="primary" @click="modal === 'model' ? saveModel() : modal === 'device' ? saveDevice() : modal === 'point' ? savePoint() : saveStation()">保存</el-button></template>
    </el-dialog>
  </div>
</template>
